/* ----- Mapping: --nt-* -> Obsidian variables (every non-default theme) ----- */
body.huhu-themed.theme-light,
body.huhu-themed.theme-dark {
	--background-primary: var(--nt-background);
	--background-primary-alt: var(--nt-card);
	--background-secondary: var(--nt-sidebar);
	--background-secondary-alt: var(--nt-chrome-muted);
	--background-modifier-border: var(--nt-border);
	--background-modifier-border-hover: var(--nt-input);
	--background-modifier-border-focus: var(--nt-ring);
	--background-modifier-hover: color-mix(in srgb, var(--nt-foreground) 7%, transparent);
	--background-modifier-active-hover: color-mix(in srgb, var(--nt-primary) 16%, transparent);
	--background-modifier-form-field: var(--nt-card);
	--background-modifier-error: var(--nt-destructive);
	--background-modifier-error-hover: color-mix(in srgb, var(--nt-destructive) 88%, var(--nt-foreground));
	--text-normal: var(--nt-foreground);
	--text-muted: var(--nt-muted-foreground);
	--text-faint: var(--nt-faint);
	--text-accent: var(--nt-link);
	--text-accent-hover: color-mix(in srgb, var(--nt-link) 82%, var(--nt-foreground));
	--text-on-accent: var(--nt-primary-foreground);
	--text-error: var(--nt-destructive);
	--text-selection: color-mix(in srgb, var(--nt-primary) 26%, transparent);
	--interactive-normal: var(--nt-secondary);
	--interactive-hover: var(--nt-accent);
	--interactive-accent: var(--nt-primary);
	--interactive-accent-hover: color-mix(in srgb, var(--nt-primary) 88%, var(--nt-foreground));
	--color-accent: var(--nt-primary);
	--color-accent-1: var(--nt-primary);
	--color-accent-2: color-mix(in srgb, var(--nt-primary) 88%, var(--nt-foreground));
	--divider-color: var(--nt-border);
	--titlebar-background: var(--nt-chrome);
	--titlebar-background-focused: var(--nt-chrome-muted);
}

/* ----- Editor colours that follow the interface theme (no editor scheme chosen) ----- */
/* .huhu-ne-follow lets the settings preview show these colours while a scheme is active. */
body.huhu-themed:not(.huhu-editor-themed).theme-light,
body.huhu-themed:not(.huhu-editor-themed).theme-dark,
.huhu-ne-follow {
	--ne-h1: var(--nt-link);
	--ne-h2: color-mix(in srgb, var(--nt-link) 68%, var(--nt-foreground));
	--ne-h3: var(--nt-foreground);
	--ne-h4: var(--nt-foreground);
	--ne-h5: var(--nt-muted-foreground);
	--ne-h6: var(--nt-muted-foreground);
	--ne-bold: var(--nt-foreground);
	--ne-italic: var(--nt-foreground);
	--ne-highlight: color-mix(in srgb, var(--nt-highlight) 30%, transparent);
	--ne-code: color-mix(in srgb, var(--nt-link) 70%, var(--nt-foreground));
	--ne-code-bg: color-mix(in srgb, var(--nt-foreground) 8%, transparent);
	--ne-link: var(--nt-link);
	--ne-quote: var(--nt-primary);
	--ne-quote-text: var(--nt-muted-foreground);
	--ne-marker: var(--nt-primary);
	--ne-tag: var(--nt-link);
	--ne-hr: var(--nt-border);
	--ne-check: var(--nt-primary);
	--ne-c-comment: var(--nt-muted-foreground);
	--ne-c-function: color-mix(in srgb, var(--nt-link) 70%, var(--nt-foreground));
	--ne-c-keyword: var(--nt-link);
	--ne-c-string: color-mix(in srgb, var(--nt-chart-2) 60%, var(--nt-foreground));
	--ne-c-property: var(--nt-foreground);
	--ne-c-value: color-mix(in srgb, var(--nt-chart-3) 60%, var(--nt-foreground));
	--ne-c-tag: var(--nt-link);
	--ne-c-punct: var(--nt-muted-foreground);
	--ne-c-important: var(--nt-destructive);
}
/* =================================================================
   HUHU editor colour schemes: Markdown element colours, independent of the interface theme.

   A scheme is a class "huhu-editor--<id>" plus the mode class on <body>; it declares --ne-*
   tokens only (headings H1-H6, bold, italic, highlight, inline code, links, quotes, list
   markers, tags, rules, checkboxes and code-block syntax). The mapping rule at the end turns
   them into Obsidian's variables, which Reading view, Live Preview and Source mode share.
   With "Follow theme" the --ne-* tokens come from the interface theme (presets.css); with the
   "Default" interface theme and "Follow theme" nothing is overridden.

   Colour values follow the published palettes named below; accents were deepened or brightened
   where a published value fails WCAG AA on common backgrounds (src/theme/presets.test.ts checks
   every scheme on every interface theme). The preview-* tokens are only used by the settings
   swatches. Palette references: GitHub Primer (MIT), Atom One (MIT), Solarized (MIT), Nord
   (MIT), Dracula (MIT), Gruvbox (MIT); the colour names are not copied from any theme file.
   ================================================================= */

