/* Layout of the scriptless Appearance preview only. Theme/Markdown styling is the real CSS. */
body.huhu-appearance-preview {
	margin: 0;
	padding: 0;
	background: var(--background-primary);
	color: var(--text-normal);
	font-family: var(--font-interface);
}
.huhu-appearance-preview :is(.app-container, .workspace) {
	display: flex;
	width: 100%;
	height: 100dvh;
	min-height: 0;
}
.huhu-appearance-preview .workspace-split.mod-sidedock {
	flex: 0 0 138px;
	flex-direction: column;
	gap: 6px;
	padding: 16px 8px;
}
.huhu-appearance-preview .workspace-split.mod-root {
	flex: 1;
	min-width: 0;
}
.huhu-appearance-preview .workspace-tabs {
	display: flex;
	flex: 1;
	flex-direction: column;
	min-width: 0;
	min-height: 0;
}
.huhu-appearance-preview .workspace-tab-header-container {
	flex-shrink: 0;
}
.huhu-appearance-preview .workspace-tab-header {
	display: flex;
	align-items: center;
	padding-inline: 12px;
}
.huhu-appearance-preview .workspace-tab-container {
	flex: 1;
	min-height: 0;
	overflow: auto;
}
.huhu-appearance-preview :is(.workspace-leaf, .workspace-leaf-content, .view-content, .markdown-reading-view) {
	position: relative;
	width: 100%;
	height: auto;
	min-height: 100%;
}
.huhu-appearance-preview .markdown-preview-view {
	height: auto;
	padding: 22px;
}
.huhu-appearance-preview .markdown-preview-sizer {
	width: 100%;
	min-height: 0;
	margin: 0 auto;
	padding: 0;
}
.huhu-appearance-preview .metadata-container {
	margin-bottom: 20px;
}
.huhu-appearance-preview .multi-select-container {
	display: flex;
	flex-wrap: wrap;
	gap: 5px;
}
.huhu-appearance-preview .multi-select-pill {
	padding: 2px 8px;
	font-size: 0.8em;
}
.huhu-appearance-preview-status {
	color: var(--text-muted);
}
.huhu-appearance-preview .huhu-appearance-preview-sample {
	font-family: var(--font-text);
}
@media (max-width: 450px) {
	.huhu-appearance-preview .workspace-split.mod-sidedock {
		display: none;
	}
	.huhu-appearance-preview .markdown-preview-view {
		padding: 16px;
	}
}
/* =================================================================
   HUHU font choices (Settings -> Appearance -> Fonts and typography).

   Interface font: Obsidian's --font-interface-theme and HUHU panels (--huhu-font-sans-user, read
   by src/ui/styles/tokens.css). Reading font: --font-text-theme. Monospace: --font-monospace-theme
   and HUHU's --huhu-font-mono-user. "Default" adds no class and leaves Obsidian's fonts alone;
   a font the user picked in Obsidian's own Appearance settings (--font-*-override) still wins.
   Every stack ends with CJK fallbacks so Chinese text never falls back to a bitmap font.
   Explicit font choices are system fonts; SuliWorld's default pairings and Geist are bundled
   offline under the SIL OFL. Aliased family names avoid colliding with a community theme.
   ================================================================= */

/* ----- Interface ----- */
body.huhu-font-interface--suliworld.theme-light {
	--huhu-font-sans-user: "HUHU Suliworld Outfit", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", "Noto Sans SC", system-ui, sans-serif;
	--font-interface-theme: var(--huhu-font-sans-user);
}
