	--font-interface-theme: var(--huhu-font-sans-user);
}
body.huhu-font-interface--host {
	--huhu-font-sans-user: var(--font-interface);
}
body.huhu-font-interface--geist {
	--huhu-font-sans-user: "Geist", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans CJK SC", "Noto Sans SC", sans-serif;
	--font-interface-theme: var(--huhu-font-sans-user);
}
