/* CodeMirror widgets live in the host editor, outside the React .huhu-ui scope. */
.huhu-sync-conflict-actions {
	display: inline-flex;
	flex-wrap: wrap;
	gap: var(--size-4-1);
	margin-inline-start: var(--size-4-2);
	vertical-align: middle;
}

.huhu-sync-conflict-button {
	height: auto;
	padding: 0 var(--size-4-2);
	font-family: var(--font-interface);
	font-size: var(--font-ui-smaller);
}
.huhu-ui .huhu-browser-workspace {
	container-type: inline-size;
}
.huhu-ui .huhu-browser-viewer canvas {
	display: block;
	touch-action: none;
}
@container (width < 600px) {
	.huhu-ui .huhu-browser-workspace-body {
		flex-direction: column;
	}
	.huhu-ui .huhu-browser-space-list {
		display: flex;
		width: 100%;
		max-height: 100px;
		gap: 4px;
		border-right: 0;
		border-bottom: 1px solid var(--border);
	}
	.huhu-ui .huhu-browser-space-list > button {
		min-width: 160px;
		max-width: 200px;
		flex-shrink: 0;
	}
}
/* Native workbench leaf boundary; internal layout is owned by React. */
.workspace-leaf-content[data-type="huhu-workbench-view"] > .view-content { padding: 0; overflow: hidden; }
body:not(.is-mobile) .workspace-leaf-content[data-type="huhu-workbench-view"] > .view-header { display: none; }
.huhu-workbench-page[hidden] { display: none; }

/* HUHU entries in Obsidian's status bar (main window only). They borrow the host's status bar metrics. */
.status-bar .huhu-status-button {
	display: inline-flex;
	align-items: center;
	gap: var(--size-2-2);
	padding: 0 var(--size-2-2);
	height: auto;
	background: transparent;
	box-shadow: none;
	border: 0;
	font: inherit;
	color: inherit;
	cursor: pointer;
}
.status-bar .huhu-status-button:hover { background-color: var(--background-modifier-hover); }
.status-bar .huhu-status-button.is-static { cursor: default; }
.status-bar .huhu-status-button.is-static:hover { background-color: transparent; }
.status-bar .huhu-status-text {
	max-width: 24ch;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	font-variant-numeric: tabular-nums;
}
.status-bar .huhu-status-item[data-tone="error"] .huhu-status-button { color: var(--text-error); }
.status-bar .huhu-status-item[data-tone="attention"] .huhu-status-button { color: var(--color-orange); }
.status-bar .huhu-status-item[data-tone="running"] .huhu-status-icon .svg-icon { animation: huhu-status-spin 1.2s linear infinite; }
@keyframes huhu-status-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
	.status-bar .huhu-status-item[data-tone="running"] .huhu-status-icon .svg-icon { animation: none; }
}
/* The usage entry hosts a React root inside .huhu-ui; keep the host's font and colour instead of HUHU's. */
.status-bar .huhu-status-usage { padding-block: 0; }
.status-bar .huhu-status-usage .huhu-status-usage-root { display: flex; align-items: center; font-family: inherit; letter-spacing: inherit; color: inherit; }
/* Hidden entries stay in the status bar as pooled, reusable items. */
.status-bar .huhu-status-item[hidden], .status-bar .huhu-status-usage[hidden] { display: none; }
